import{c as s,Q as n,j as e,m as t}from"./chunks/framework.DOi4mjdC.js";const p="/assets/%E7%AE%97%E5%AD%90%E5%BC%80%E5%8F%91%E7%AB%AF%E5%88%B0%E7%AB%AF%E6%B5%81%E7%A8%8B-67.YGV5y88C.png",c=JSON.parse('{"title":"FormatForBinQuery","description":"","frontmatter":{},"headers":[{"level":1,"title":"FormatForBinQuery","slug":"formatforbinquery"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/Utils-API/原型注册与管理/OpParamDef/FormatForBinQuery.md","filePath":"api/Utils-API/原型注册与管理/OpParamDef/FormatForBinQuery.md"}'),l={name:"api/Utils-API/原型注册与管理/OpParamDef/FormatForBinQuery.md"};function i(r,a,o,F,g,T){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="formatforbinquery" tabindex="-1">FormatForBinQuery <a class="header-anchor" href="#formatforbinquery" aria-label="Permalink to &quot;FormatForBinQuery&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>设置Input/Output用于运行时算子二进制查找的数据格式，和<a href="./Format.html">Format</a>/<a href="./FormatList.html">FormatList</a>的数量一致，且一一对应。</p><p>算子编译过程中，会根据数据格式生成多个.o，并通过这些数据格式在运行时索引算子二进制。某些算子支持多种数据格式，且对数据格式不敏感，这时可以使用该接口，将多种数据格式映射到同一个算子二进制，多个数据格式可以复用一个.o，从而减少二进制文件的生成。</p><p>例如，如果一个算子的输入支持多种数据格式（ge::FORMAT_NC和ge::FORMAT_ND），并且使用ge::FORMAT_NC输入时可以复用ge::FORMAT_ND的二进制文件而不影响最终结果，那么可以采用如下配置：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_INT16, ge::DT_INT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_NC, ge::FORMAT_ND})</span></span>
<span class="line"><span>            .FormatForBinQuery({ge::FORMAT_ND,ge::FORMAT_ND});</span></span></code></pre></div><p>这样，只需生成一个目标文件（.o），就能实现对多种数据格式的支持。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OpParamDef &amp;FormatForBinQuery(std::vector&lt;ge::Format&gt; formats)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>输入/输出</th><th>说明</th></tr></thead><tbody><tr><td>formats</td><td>输入</td><td>算子参数数据格式。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>OpParamDef算子定义，OpParamDef请参考<a href="./OpParamDef.html">OpParamDef</a>。</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>FormatForBinQuery的参数个数需要和当前算子参数的Format或者FormatList的参数个数保持一致。</li><li>不支持与<a href="./Scalar.html">Scalar</a>/<a href="./ScalarList.html">ScalarList</a>同时使用。</li><li>不支持与<a href="./ValueDepend.html">ValueDepend</a>同时使用。</li><li>设置FormatForBinQuery后，会用FormatForBinQuery的数据格式替换当前Input/Output的数据格式，并检查新组合在替换前是否存在。如果存在，则指向对应的二进制，如果不存在，该参数失效，按照原来的数据格式生成。具体请参考<a href="#li26512368417">示例一</a>。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><ul><li><p>示例一</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_NC, ge::FORMAT_NCHW, ge::FORMAT_NHWC, ge::FORMAT_ND})</span></span>
<span class="line"><span>            .FormatForBinQuery({ge::FORMAT_NC, ge::FORMAT_NC, ge::FORMAT_ND, ge::FORMAT_NCHW});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_NC, ge::FORMAT_ND});</span></span></code></pre></div><p>如下图所示，没有设置FormatForBinQuery之前，会生成4个二进制。通过上述代码设置FormatForBinQuery后：</p><ul><li>替换后第4列使用原来第2列的二进制，第1列和第2列使用原来第1列的二进制。第3列仍使用第3列的二进制。</li><li>替换后，第1列和第2列完全一致，达成二进制复用的效果，算子总二进制会由原来的四个（bin1，bin2，bin3，bin4）缩减至现在的三个（bin1，bin2、bin3）。</li></ul><p><img src="`+p+`" alt=""></p></li><li><p>示例二</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        // 简单用例，此时会有两对复用，1、2列-&gt;1列，3、4列-&gt;4列。总共生成1、4两个二进制。所有支持的Format会传入这两个二进制运行。</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_NC, ge::FORMAT_NCHW, ge::FORMAT_NHWC, ge::FORMAT_ND})</span></span>
<span class="line"><span>            .FormatForBinQuery({ge::FORMAT_NC, ge::FORMAT_NC, ge::FORMAT_ND, ge::FORMAT_ND});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT, ge::DT_FLOAT})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND, ge::FORMAT_ND});</span></span></code></pre></div></li><li><p>示例三</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        // 复杂用例，可以多个Input/Output同时使用FormatBinQuery，此时也会产生两对复用。1、2列-&gt;1列，3、4列-&gt;3列。总共生成1、3两个二进制。所有支持的Format会传入这两个二进制运行。</span></span>
<span class="line"><span>        this-&gt;Input(&quot;x&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_NC, ge::FORMAT_NCHW, ge::FORMAT_NHWC, ge::FORMAT_ND})</span></span>
<span class="line"><span>            .FormatForBinQuery({ge::FORMAT_NC, ge::FORMAT_NC, ge::FORMAT_NHWC, ge::FORMAT_NHWC});</span></span>
<span class="line"><span>        this-&gt;Input(&quot;y&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_NC, ge::FORMAT_NCHW, ge::FORMAT_NHWC, ge::FORMAT_ND})</span></span>
<span class="line"><span>            .FormatForBinQuery({ge::FORMAT_NC, ge::FORMAT_NC, ge::FORMAT_NHWC, ge::FORMAT_NHWC});</span></span>
<span class="line"><span>        this-&gt;Output(&quot;z&quot;)</span></span>
<span class="line"><span>            .ParamType(REQUIRED)</span></span>
<span class="line"><span>            .DataType({ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16, ge::DT_FLOAT16})</span></span>
<span class="line"><span>            .Format({ge::FORMAT_NC, ge::FORMAT_NCHW, ge::FORMAT_NHWC, ge::FORMAT_ND})</span></span>
<span class="line"><span>            .FormatForBinQuery({ge::FORMAT_NC, ge::FORMAT_NC, ge::FORMAT_NHWC, ge::FORMAT_NHWC});</span></span></code></pre></div></li></ul>`,17)])])}const _=s(l,[["render",i]]);export{c as __pageData,_ as default};
